insert into public.sq_iq_items(id,bank_version,band,domain,payload) values('iq-1-2-logic-0-0',1,2,'logic','{"id":"iq-1-2-logic-0-0","domain":"logic","prompt":"Barcha P guruhidagilar — Q guruhidagilar. Barcha Q guruhidagilar — R guruhidagilar. Qaysi xulosa albatta kelib chiqadi?","visual":{"kind":"sets","labels":["X","Y","Z"],"legend":["P guruhidagilar","Q guruhidagilar","R guruhidagilar"]},"options":["Hech bir P guruhidagilar — R guruhidagilar emas.","Barcha R guruhidagilar — Q guruhidagilar.","Barcha P guruhidagilar — R guruhidagilar.","Barcha R guruhidagilar — P guruhidagilar."],"answer":2,"explanation":"Birinchi to‘plam ikkinchisining, ikkinchisi uchinchisining ichida. Demak birinchisi uchinchiga kiradi; teskari yo‘nalish kafolatlanmaydi."}'::jsonb) on conflict(id) do nothing;
